import React from 'react';
import { TrendingUp, TrendingDown } from 'lucide-react';

/**
 * Canlı USK & Tarım Piyasa Fiyat Ticker'ı
 * Çiftçiye güncel çiğ süt tavsiye fiyatı, karkas et ve yem borsa endekslerini anlık sunar.
 */
export default function MarketTickerBar() {
  const marketIndices = [
    { label: 'USK Çiğ Süt Ref.', price: '14,65 ₺/L', change: '+2.4%', isUp: true },
    { label: 'Dana Karkas (Borsa)', price: '348,00 ₺/kg', change: '+1.8%', isUp: true },
    { label: 'Kuzu Karkas (Borsa)', price: '385,00 ₺/kg', change: '+0.5%', isUp: true },
    { label: 'Süt Yemi (50kg)', price: '585,00 ₺', change: '-1.2%', isUp: false },
    { label: 'Süt/Yem Paritesi', price: '1,38', change: 'İdeal (>1.30)', isUp: true }
  ];

  return (
    <div className="w-full bg-slate-900 text-white px-4 py-2 rounded-2xl flex items-center justify-between gap-4 overflow-x-auto text-xs shadow-xs scrollbar-none animate-in fade-in select-none">
      <div className="flex items-center gap-1.5 flex-shrink-0 text-emerald-400 font-bold uppercase tracking-wider text-[10px]">
        <span className="w-2 h-2 rounded-full bg-emerald-400 animate-ping" />
        Piyasa Endeksleri
      </div>

      <div className="flex items-center gap-6 overflow-x-auto whitespace-nowrap scrollbar-none">
        {marketIndices.map((idx, i) => (
          <div key={i} className="flex items-center gap-2">
            <span className="text-slate-400 font-medium">{idx.label}:</span>
            <strong className="text-white font-bold">{idx.price}</strong>
            <span className={`flex items-center gap-0.5 text-[10px] font-black ${
              idx.isUp ? 'text-emerald-400' : 'text-amber-400'
            }`}>
              {idx.isUp ? <TrendingUp className="w-3 h-3" /> : <TrendingDown className="w-3 h-3" />}
              {idx.change}
            </span>
          </div>
        ))}
      </div>
    </div>
  );
}
