import React, { useState } from 'react';
import { Share2, MessageCircle, Copy, Check, X } from 'lucide-react';
import toast from 'react-hot-toast';

/**
 * WhatsApp & SMS Gün Sonu Yönetici Özeti
 * Çiftlik yöneticisine veya sahibine tek tıkla WhatsApp ve SMS formatında günlük brifing metni üretir.
 */

export default function DailyDigestShareModal({ isOpen, onClose, farmName = 'mFk Farm', stats = {} }) {
  const [copied, setCopied] = useState(false);

  if (!isOpen) return null;

  const today = new Date().toLocaleDateString('tr-TR', { day: 'numeric', month: 'long', year: 'numeric' });
  const totalMilk = stats.totalMilk || '1.450';
  const milkingCount = stats.milkingCount || '48';
  const births = stats.births || '2';
  const treated = stats.treated || '1';
  const revenue = stats.revenue || '21.370';

  const digestText = `🚜 *${farmName.toUpperCase()} — GÜN SONU BRİFİNGİ*
📅 *Tarih:* ${today}

🥛 *Süt Üretimi:*
• Toplam Sağım: *${totalMilk} L* (${milkingCount} sağmal)
• Ortalama Verim: *${(parseFloat(totalMilk) / parseFloat(milkingCount)).toFixed(1)} L/baş*

🍼 *Sürü & Üreme:*
• Yeni Doğan Buzağı/Kuzu: *${births} baş*
• Tedavideki Hayvan: *${treated} baş (Sütü tanka verilmedi)*

💰 *Mali Özet:*
• Tahmini Günlük Brüt Hakediş: *₺${revenue}*

_mFk Farm Akıllı Çiftlik Yönetim Sistemi tarafından otomatik oluşturuldu._`;

  const handleCopy = () => {
    navigator.clipboard.writeText(digestText);
    setCopied(true);
    toast.success('Rapor panoya kopyalandı!');
    setTimeout(() => setCopied(false), 2500);
  };

  const handleShareWhatsApp = () => {
    const encoded = encodeURIComponent(digestText);
    window.open(`https://api.whatsapp.com/send?text=${encoded}`, '_blank');
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-3 bg-black/60 backdrop-blur-xs">
      <div className="bg-white w-full max-w-md rounded-2xl shadow-xl overflow-hidden border border-gray-100">
        <div className="bg-emerald-700 text-white p-4 flex items-center justify-between">
          <div className="flex items-center gap-2">
            <Share2 className="w-5 h-5 text-emerald-200" />
            <h3 className="font-bold text-sm">Gün Sonu Yönetici Brifingi</h3>
          </div>
          <button onClick={onClose} className="text-white/80 hover:text-white">
            <X className="w-5 h-5" />
          </button>
        </div>

        <div className="p-4 space-y-3">
          <p className="text-xs text-gray-500">
            Aşağıdaki özet raporu çiftlik sahibine veya ortaklara WhatsApp veya SMS ile tek tıkla iletebilirsiniz:
          </p>

          <div className="bg-gray-50 border border-gray-200 rounded-xl p-3 text-xs font-mono whitespace-pre-line text-gray-800 max-h-60 overflow-y-auto leading-relaxed">
            {digestText}
          </div>

          <div className="flex items-center gap-2 pt-2">
            <button
              onClick={handleCopy}
              className="btn-secondary flex-1 text-xs py-2 px-3 flex items-center justify-center gap-1.5 font-bold"
            >
              {copied ? <Check className="w-3.5 h-3.5 text-emerald-600" /> : <Copy className="w-3.5 h-3.5" />}
              {copied ? 'Kopyalandı!' : 'Metni Kopyala'}
            </button>

            <button
              onClick={handleShareWhatsApp}
              className="bg-emerald-600 hover:bg-emerald-700 text-white flex-1 text-xs py-2 px-3 rounded-xl flex items-center justify-center gap-1.5 font-bold transition shadow-xs"
            >
              <MessageCircle className="w-3.5 h-3.5" />
              WhatsApp ile Paylaş
            </button>
          </div>
        </div>
      </div>
    </div>
  );
}
