import React, { useState } from 'react';
import { Bot, Send, Sparkles, X, ChevronRight } from 'lucide-react';

/**
 * mFk Farm AI Çiftlik Asistanı & Veri Danışmanı
 * Sürü verilerine dayalı akıllı veterinerlik, rasyon optimizasyonu ve üretim tavsiyeleri üretir.
 */

const QUICK_PROMPTS = [
  { id: 'repro', title: 'Tohumlama Analizi', query: 'Son 60 günde tohumlanmamış veya östrus göstermemiş sağmalları analiz et.' },
  { id: 'milk', title: 'Süt Verim Düşüşü', query: 'Son 7 günde sağım litresi %15ten fazla azalan hayvanlar ve olası nedenler nelerdir?' },
  { id: 'feed', title: 'Rasyon Tasarrufu', query: 'TMR yem rasyonunda süt verimini düşürmeden kaba-kesif yem maliyetini nasıl %10 optimize edebilirim?' },
  { id: 'mastitis', title: 'Mastitis Erken Uyarı', query: 'CMT şüpheli çıkan çeyrekler için antibiyotiksiz erken sağaltım protokolü nedir?' }
];

export default function AiFarmAdvisorModal({ isOpen, onClose, farmData = {} }) {
  const [messages, setMessages] = useState([
    {
      id: 1,
      sender: 'ai',
      text: 'Merhaba! Ben mFk Farm AI Çiftlik Danışmanınız. Sürünüzün süt verimi, üreme takvimi, rasyon maliyeti veya veterinerlik konularında analizler yapabilirim. Size nasıl yardımcı olabilirim?',
      time: 'Şimdi'
    }
  ]);
  const [input, setInput] = useState('');
  const [loading, setLoading] = useState(false);

  if (!isOpen) return null;

  const handleSend = (textToSend) => {
    const query = textToSend || input;
    if (!query.trim()) return;

    const userMsg = {
      id: Date.now(),
      sender: 'user',
      text: query,
      time: new Date().toLocaleTimeString('tr-TR', { hour: '2-digit', minute: '2-digit' })
    };

    setMessages(prev => [...prev, userMsg]);
    if (!textToSend) setInput('');
    setLoading(true);

    // Kural tabanlı / Akıllı AI simülasyon cevabı
    setTimeout(() => {
      let replyText = '';
      const q = query.toLowerCase();

      if (q.includes('tohum') || q.includes('östrus') || q.includes('üreme')) {
        replyText = `📊 **Üreme Analizi:**\n• Çiftliğinizde gebelik muayenesi bekleyen 3 baş hayvan tespit edildi.\n• Doğumdan sonra 70 günü geçmiş ve henüz tohumlanmamış sağmallar için PGF2α protokolü veya ultrason taraması önerilir.\n• Tohumlama indeksi hedefiniz: 1.6 payet/gebelik.`;
      } else if (q.includes('süt') || q.includes('verim') || q.includes('litre')) {
        replyText = `🥛 **Süt Verim Raporu:**\n• Sürü ortalaması: ~28.4 L/gün. 305 günlük Wood laktasyon eğrisine göre 50-70. gün arası pik seviye yakalanmış.\n• Verimi düşen sağmallarda asidoz (SARA) veya gizli mastitis taraması yapılması önerilir.`;
      } else if (q.includes('rasyon') || q.includes('yem') || q.includes('maliyet')) {
        replyText = `🌾 **Rasyon Optimizasyon Tavsiyesi:**\n• Mısır silajı kuru maddesini %34'te tutarak fabrika yemi tüketimini hayvan başı 1.2 kg azaltabilirsiniz.\n• Bu optimizasyon günlük sürü bazında yaklaşık ₺850 tasarruf sağlar.`;
      } else if (q.includes('mastitis') || q.includes('cmt') || q.includes('meme')) {
        replyText = `🛡️ **Mastitis Protokolü:**\n• CMT skor 1 (şüpheli) loblar için sağım öncesi daldırma solüsyonunun temas süresini 30 saniyeye çıkarın.\n• Nane yağı bazlı meme jelleri ve sık sağım ile klinik safhaya geçişi %70 oranında engelleyebilirsiniz.`;
      } else {
        replyText = `🔍 **Çiftlik Değerlendirmesi:**\nSistem kayıtlarınıza göre çiftlik yönetim parametreleriniz aktif olarak izleniyor. İlaç arınma sürelerine dikkat edilmesi, lohusa ineklerde ketozis riski için idrar stripi kontrolü ve kuru dönem rasyonunda kalsiyum kısıtlaması önerilir.`;
      }

      setMessages(prev => [
        ...prev,
        {
          id: Date.now() + 1,
          sender: 'ai',
          text: replyText,
          time: new Date().toLocaleTimeString('tr-TR', { hour: '2-digit', minute: '2-digit' })
        }
      ]);
      setLoading(false);
    }, 700);
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-3 bg-black/60 backdrop-blur-xs">
      <div className="bg-white w-full max-w-xl rounded-2xl shadow-2xl overflow-hidden flex flex-col h-[600px] border border-gray-100 animate-in fade-in zoom-in-95">
        {/* Modal Başlığı */}
        <div className="bg-gradient-to-r from-emerald-600 to-teal-700 text-white p-4 flex items-center justify-between">
          <div className="flex items-center gap-2.5">
            <div className="p-2 bg-white/20 rounded-xl backdrop-blur-xs">
              <Bot className="w-5 h-5 text-white" />
            </div>
            <div>
              <div className="flex items-center gap-1.5">
                <h3 className="font-bold text-sm">mFk Farm AI Çiftlik Danışmanı</h3>
                <span className="px-1.5 py-0.2 bg-emerald-400/30 text-emerald-100 rounded text-[10px] font-semibold flex items-center gap-1">
                  <Sparkles className="w-2.5 h-2.5" /> Canlı
                </span>
              </div>
              <p className="text-xs text-emerald-100 opacity-90">Sürü verisi ve veterinerlik analitiği</p>
            </div>
          </div>
          <button onClick={onClose} className="text-white/80 hover:text-white p-1 rounded-lg">
            <X className="w-5 h-5" />
          </button>
        </div>

        {/* Hızlı Sorular */}
        <div className="bg-emerald-50/50 p-2.5 border-b border-emerald-100 overflow-x-auto flex gap-2 shrink-0">
          {QUICK_PROMPTS.map(p => (
            <button
              key={p.id}
              onClick={() => handleSend(p.query)}
              className="text-[11px] font-semibold bg-white border border-emerald-200 text-emerald-800 px-2.5 py-1 rounded-full whitespace-nowrap hover:bg-emerald-100 transition flex items-center gap-1 shadow-2xs"
            >
              <span>{p.title}</span>
              <ChevronRight className="w-3 h-3 text-emerald-600" />
            </button>
          ))}
        </div>

        {/* Mesaj Akışı */}
        <div className="flex-1 overflow-y-auto p-4 space-y-3.5 bg-gray-50/50">
          {messages.map((m) => (
            <div
              key={m.id}
              className={`flex items-start gap-2.5 ${m.sender === 'user' ? 'flex-row-reverse' : ''}`}
            >
              <div className={`w-7 h-7 rounded-full flex items-center justify-center shrink-0 text-xs font-bold ${m.sender === 'user' ? 'bg-blue-600 text-white' : 'bg-emerald-600 text-white'}`}>
                {m.sender === 'user' ? 'Sen' : <Bot className="w-4 h-4" />}
              </div>
              <div className={`max-w-[82%] p-3 rounded-2xl text-xs leading-relaxed ${m.sender === 'user' ? 'bg-blue-600 text-white rounded-tr-none' : 'bg-white border border-gray-100 text-gray-800 shadow-xs rounded-tl-none'}`}>
                <div className="whitespace-pre-line">{m.text}</div>
                <span className={`block text-[9px] mt-1 text-right ${m.sender === 'user' ? 'text-blue-200' : 'text-gray-400'}`}>
                  {m.time}
                </span>
              </div>
            </div>
          ))}

          {loading && (
            <div className="flex items-center gap-2 text-xs text-gray-400 bg-white p-3 rounded-xl border border-gray-100 w-fit">
              <Sparkles className="w-4 h-4 text-emerald-600 animate-spin" />
              <span>Sürü verileri taranıyor ve analiz üretiliyor...</span>
            </div>
          )}
        </div>

        {/* Soru Giriş Alanı */}
        <div className="p-3 bg-white border-t border-gray-100 flex items-center gap-2">
          <input
            type="text"
            value={input}
            onChange={(e) => setInput(e.target.value)}
            onKeyDown={(e) => e.key === 'Enter' && handleSend()}
            placeholder="Sürünüz, rasyon veya sağlık hakkında soru sorun..."
            className="flex-1 text-xs border border-gray-200 rounded-xl px-3.5 py-2.5 focus:outline-none focus:border-emerald-500 focus:ring-1 focus:ring-emerald-500 bg-gray-50/70"
          />
          <button
            onClick={() => handleSend()}
            disabled={!input.trim() || loading}
            className="btn-primary text-xs py-2.5 px-3.5 flex items-center gap-1 font-bold disabled:opacity-40"
          >
            <Send className="w-3.5 h-3.5" />
          </button>
        </div>
      </div>
    </div>
  );
}
